/** Imported originals, legacy opening balances and full payment correction use the real rules. */
public final class IssuedInvoiceRulesTests {
    private static int checks;
    private static void yes(boolean value){checks++;if(!value)throw new AssertionError("Issued/imported invoice check "+checks);}
    private static JSONObject imported()throws Exception{return new JSONObject().put("id","qa_imported_invoice").put("customer_id","qa_customer").put("invoice_number","QA-2027-0077").put("sevdesk_id","qa_sevdesk_document").put("issued_at","").put("status","Gestellt").put("amount",148).put("worklog_ids",new JSONArray());}
    private static JSONObject effective(JSONObject invoice)throws Exception{return new JSONObject().put("invoices",new JSONArray().put(invoice)).put("worklogs",new JSONArray());}
    private static JSONObject payment(String id,long amount)throws Exception{return new JSONObject().put("formatVersion",1).put("payment_id",id).put("request_id","qa_request_"+id).put("client_request_id","qa_client_"+id).put("amount_minor",amount).put("unallocated_minor",0).put("paid_on","2027-05-18").put("method","bank").put("recorded_at","2027-05-18T18:00:00Z").put("allocations",new JSONArray().put(new JSONObject().put("invoice_id","qa_imported_invoice").put("amount_minor",amount)));}
    private static JSONObject reversal()throws Exception{return new JSONObject().put("formatVersion",1).put("payment_id","qa_void_reversal").put("amount_minor",-6000).put("reversal",true).put("reverses","qa_received").put("reason","QA falsche Zahlung vollständig zurückgenommen").put("recorded_at","2027-05-18T19:00:00Z").put("allocations",new JSONArray().put(new JSONObject().put("invoice_id","qa_imported_invoice").put("amount_minor",-6000)));}
    private static JSONObject zero()throws Exception{return payment("qa_void",0).put("allocations",new JSONArray()).put("corrects","qa_received").put("reason","QA falsche Zahlung vollständig zurückgenommen");}
    private static JSONObject corrected()throws Exception{return new JSONObject().put("local_payment:qa_received",payment("qa_received",6000)).put("local_payment:qa_void_reversal",reversal()).put("local_payment:qa_void",zero());}
    private static void denied(JSONObject state,JSONObject namespace)throws Exception {String before=PixelMcpWriteTools.hash(new JSONArray().put(state).put(namespace));try{LocalFinancialValidation.inspect(state,namespace);throw new AssertionError("Expected financial rejection");}catch(IOException expected){yes(expected.getMessage().startsWith("FINANCIAL_"));}yes(before.equals(PixelMcpWriteTools.hash(new JSONArray().put(state).put(namespace))));}
    public static void main(String[] args)throws Exception {
        JSONObject imported=imported();String original=PixelMcpWriteTools.hash(imported);yes(IssuedInvoiceRules.isIssued(imported));yes(!IssuedInvoiceRules.isIssued(new JSONObject(imported.toString()).put("status","Entwurf")));yes(!IssuedInvoiceRules.isIssued(new JSONObject().put("status","Gestellt")));yes(!IssuedInvoiceRules.isIssued(new JSONObject().put("status","Bezahlt")));yes(IssuedInvoiceRules.isIssued(new JSONObject().put("issued_at","2027-05-18T18:00:00Z").put("status","Entwurf")));
        JSONObject namespace=new JSONObject().put("invoice_opening_balance:qa_imported_invoice",new JSONObject().put("invoice_id","qa_imported_invoice").put("remaining_minor",14800)).put("local_payment:qa_received",payment("qa_received",6000));yes(LocalFinancialValidation.inspect(effective(imported),namespace).getString("status").equals("PASS"));yes(imported.getString("issued_at").isEmpty()&&original.equals(PixelMcpWriteTools.hash(imported)));
        JSONObject complete=corrected();String completeHash=PixelMcpWriteTools.hash(complete);yes(LocalFinancialValidation.inspect(effective(imported),complete).getJSONObject("counts").getInt("payments")==3);JSONArray allocated=new JSONArray();for(String key:new String[]{"local_payment:qa_received","local_payment:qa_void_reversal"}){JSONObject row=complete.getJSONObject(key);allocated.put(new JSONObject().put("payment_id",row.getString("payment_id")).put("allocated_minor",row.getJSONArray("allocations").getJSONObject(0).getLong("amount_minor")));}JSONObject balance=LocalAuthorityRules.paymentBalance(14800,allocated);yes(balance.getLong("remaining_minor")==14800&&!balance.getBoolean("paid"));yes(completeHash.equals(PixelMcpWriteTools.hash(complete))&&complete.getJSONObject("local_payment:qa_received").getLong("amount_minor")==6000);
        Map<String,String> receipts=new HashMap<>();OwnerRequestTransactions.Store storage=new OwnerRequestTransactions.Store(){public void begin(){}public String read(String key){return receipts.getOrDefault(key,"");}public void write(String key,String value){receipts.put(key,value);}public void successful(){}public void end(){}};String fingerprint=PixelMcpWriteTools.hash(complete);int[] writes={0};OwnerRequestTransactions.runRequest(storage,"qa_zero_correction_request",fingerprint,()->{writes[0]++;LocalFinancialValidation.inspect(effective(imported),complete);return new JSONObject().put("payment_id","qa_void");},"2027-05-18T19:00:00Z");yes(OwnerRequestTransactions.runRequest(storage,"qa_zero_correction_request",fingerprint,()->{throw new AssertionError("Same correction must not run twice");},"2027-05-18T19:01:00Z").getBoolean("replayed")&&writes[0]==1);
        denied(effective(imported),new JSONObject().put("local_payment:qa_record_zero",payment("qa_record_zero",0).put("allocations",new JSONArray())));denied(effective(imported),new JSONObject().put("local_payment:qa_void",zero()));JSONObject invalid=corrected();invalid.getJSONObject("local_payment:qa_void").put("allocations",new JSONArray().put(new JSONObject().put("invoice_id","qa_imported_invoice").put("amount_minor",1)));denied(effective(imported),invalid);invalid=corrected();invalid.getJSONObject("local_payment:qa_void_reversal").put("amount_minor",-5999);denied(effective(imported),invalid);denied(effective(new JSONObject(imported.toString()).put("status","Entwurf")),namespace);denied(effective(new JSONObject(imported.toString()).put("sevdesk_id","")),namespace);
        Path root=Files.createTempDirectory("qa_imported_original_");try{
            byte[] bytes="%PDF-1.4\nQA synthetic imported original\n%%EOF".getBytes(StandardCharsets.US_ASCII);Path first=root.resolve("qa_original.pdf");Files.write(first,bytes);String sha=EncryptedBackupArchive.sha256(first.toFile());Path documents=root.resolve("business-documents");Files.createDirectories(documents);Files.move(first,documents.resolve(sha+".pdf"));imported.put("pdf_sha256",sha).put("pdf_storage_name",sha+".pdf").put("pdf_byte_size",bytes.length);JSONObject master=new JSONObject();for(String name:new String[]{"customers","orders","worklogs","photos","offers","invoices","appointments","service_catalog"})master.put(name,new JSONArray());master.getJSONArray("customers").put(new JSONObject().put("id","qa_customer"));master.getJSONArray("invoices").put(imported);JSONObject state=new JSONObject().put("master",master).put("pending",new JSONArray()),before=new JSONObject(state.toString());LocalMigrationInventory.Originals verifier=(kind,reference)->LocalFinancialOriginals.inspect(root.toFile(),new JSONObject().put("issued",new JSONArray().put(new JSONObject().put("pdf_sha256",reference.getString("pdf_sha256")).put("pdf_byte_size",reference.getLong("pdf_byte_size"))))).getBoolean("original_files_verified");JSONObject inventory=LocalMigrationInventory.inspect(state,verifier);yes(inventory.getInt("verified_local_originals")==1&&inventory.getInt("missing_local_originals")==0);yes(PixelMcpWriteTools.hash(before).equals(PixelMcpWriteTools.hash(state))&&imported.getString("issued_at").isEmpty());Files.write(documents.resolve(sha+".pdf"),"%PDF-QA damaged".getBytes(StandardCharsets.US_ASCII));yes(LocalMigrationInventory.inspect(state,verifier).getInt("missing_local_originals")==1);
        }finally{try(java.util.stream.Stream<Path> paths=Files.walk(root)){for(Path path:(Iterable<Path>)paths.sorted(Comparator.reverseOrder())::iterator)Files.delete(path);}}
        System.out.println("PASS "+checks+" imported-original/empty-issue-date/opening-payment/full-reversal/replay/corruption checks; no invented dates or status-only issue authority");
    }
}
